<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Todo App</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #f0f2f5; color: #333; display: flex; justify-content: center; min-height: 100vh; padding: 40px 20px; }
  .container { width: 100%; max-width: 520px; background: #fff; border-radius: 12px; box-shadow: 0 2px 12px rgba(0,0,0,0.08); padding: 32px; }
  h1 { text-align: center; margin-bottom: 24px; font-size: 28px; color: #1a1a2e; }
  .input-row { display: flex; gap: 8px; margin-bottom: 20px; }
  .input-row input { flex: 1; padding: 12px 16px; border: 2px solid #e0e0e0; border-radius: 8px; font-size: 16px; transition: border-color 0.2s; outline: none; }
  .input-row input:focus { border-color: #4a90d9; }
  .btn-add { padding: 12px 24px; background: #4a90d9; color: #fff; border: none; border-radius: 8px; font-size: 16px; cursor: pointer; white-space: nowrap; transition: background 0.2s; }
  .btn-add:hover { background: #357abd; }
  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
  .filters button { padding: 8px 16px; border: 1.5px solid #ddd; border-radius: 6px; background: #fff; cursor: pointer; font-size: 14px; color: #555; transition: all 0.2s; }
  .filters button.active { background: #4a90d9; color: #fff; border-color: #4a90d9; }
  .filters button:hover:not(.active) { background: #f5f5f5; }
  .todo-list { list-style: none; }
  .todo-list li { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-bottom: 1px solid #eee; }
  .todo-list li:last-child { border-bottom: none; }
  .todo-list li.completed span { text-decoration: line-through; color: #999; }
  .todo-list li .check { width: 22px; height: 22px; border: 2px solid #ccc; border-radius: 50%; cursor: pointer; flex-shrink: 0; transition: all 0.2s; display: flex; align-items: center; justify-content: center; }
  .todo-list li .check:hover { border-color: #4a90d9; background: #eaf4ff; }
  .todo-list li .check.checked { background: #4a90d9; border-color: #4a90d9; }
  .todo-list li .check.checked::after { content: "✓"; color: #fff; font-size: 14px; font-weight: bold; }
  .todo-list li .text { flex: 1; font-size: 15px; line-height: 1.4; }
  .todo-list li .delete { background: none; border: none; color: #e74c3c; cursor: pointer; font-size: 18px; padding: 4px 8px; border-radius: 4px; transition: opacity 0.2s; }
  .todo-list li .delete:hover { background: #ffeaea; opacity: 0.8; }
  .empty { text-align: center; color: #aaa; padding: 24px 0; font-size: 15px; }
</style>
</head>
<body>
<div class="container">
  <h1>📝 Todo List</h1>
  <div class="input-row">
    <input type="text" id="todoInput" placeholder="Add a new todo..." autocomplete="off">
    <button class="btn-add" id="addBtn">Add</button>
  </div>
  <div class="filters">
    <button class="active" data-filter="all">All</button>
    <button data-filter="active">Active</button>
    <button data-filter="completed">Completed</button>
  </div>
  <ul class="todo-list" id="todoList"></ul>
</div>

<script>
  // State
  let todos = JSON.parse(localStorage.getItem('todos') || '[]');

  // DOM
  const input = document.getElementById('todoInput');
  const addBtn = document.getElementById('addBtn');
  const list = document.getElementById('todoList');
  const filterBtns = document.querySelectorAll('.filters button');
  let currentFilter = 'all';

  // Add
  function addTodo() {
    const text = input.value.trim();
    if (!text) return;
    todos.unshift({ id: Date.now(), text, completed: false });
    input.value = '';
    save();
    render();
  }
  addBtn.addEventListener('click', addTodo);
  input.addEventListener('keydown', e => { if (e.key === 'Enter') addTodo(); });

  // Toggle complete
  function toggle(id) {
    const t = todos.find(x => x.id === id);
    if (t) { t.completed = !t.completed; save(); render(); }
  }

  // Delete
  function remove(id) {
    todos = todos.filter(x => x.id !== id);
    save();
    render();
  }

  // Filter
  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => { currentFilter = btn.dataset.filter; render(); });
  });

  // Save
  function save() { localStorage.setItem('todos', JSON.stringify(todos)); }

  // Render
  function render() {
    list.innerHTML = '';
    const filtered = todos.filter(t => {
      if (currentFilter === 'active') return !t.completed;
      if (currentFilter === 'completed') return t.completed;
      return true;
    });
    if (filtered.length === 0) {
      list.innerHTML = '<li class="empty">No todos yet</li>';
      return;
    }
    filtered.forEach(t => {
      const li = document.createElement('li');
      li.className = t.completed ? 'completed' : '';
      li.innerHTML = `
        <div class="check ${t.completed ? 'checked' : ''}" data-id="${t.id}" onclick="toggle(${t.id})"></div>
        <span class="text">${escapeHtml(t.text)}</span>
        <button class="delete" data-id="${t.id}" onclick="remove(${t.id})">×</button>
      `;
      list.appendChild(li);
    });
  }

  function escapeHtml(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  render();
</script>
</body>
</html>"}
